lties/homeowner-claim-appraisal/"}},{"@type":"Offer","itemOffered":{"@type":"Service","name":"Condo, AOAO & Commercial","url":"https://hawaiiinsuranceappraiser.com/appraisal-specialties/condo-aoao-commercial-appraisal/"}},{"@type":"Offer","itemOffered":{"@type":"Service","name":"Roof & Hail Claims","url":"https://hawaiiinsuranceappraiser.com/appraisal-specialties/roof-hail-claim-appraisal/"}},{"@type":"Offer","itemOffered":{"@type":"Service","name":"Kona Storm & High-Wind Claims","url":"https://hawaiiinsuranceappraiser.com/appraisal-specialties/kona-storm-high-wind-claims/"}},{"@type":"Offer","itemOffered":{"@type":"Service","name":"Hurricane Claim Appraisal","url":"https://hawaiiinsuranceappraiser.com/appraisal-specialties/hurricane-claim-appraisal/"}},{"@type":"Offer","itemOffered":{"@type":"Service","name":"Water Damage Claims","url":"https://hawaiiinsuranceappraiser.com/appraisal-specialties/water-damage-claim-appraisal/"}},{"@type":"Offer","itemOffered":{"@type":"Service","name":"Fire & Smoke Claims","url":"https://hawaiiinsuranceappraiser.com/appraisal-specialties/fire-smoke-claim-appraisal/"}},{"@type":"Offer","itemOffered":{"@type":"Service","name":"Wildfire Claim Appraisal","url":"https://hawaiiinsuranceappraiser.com/appraisal-specialties/wildfire-claim-appraisal/"}},{"@type":"Offer","itemOffered":{"@type":"Service","name":"Volcanic, Ash & Lava Claims","url":"https://hawaiiinsuranceappraiser.com/appraisal-specialties/volcanic-ashfall-lava-claims/"}},{"@type":"Offer","itemOffered":{"@type":"Service","name":"Carrier Estimate Review","url":"https://hawaiiinsuranceappraiser.com/appraisal-specialties/carrier-estimate-review/"}},{"@type":"Offer","itemOffered":{"@type":"Service","name":"Umpire Services","url":"https://hawaiiinsuranceappraiser.com/appraisal-specialties/umpire-services/"}}]},"knowsAbout":["Insurance appraisal","Appraisal clause","Property claim valuation","Hurricane deductibles","Condominium master policies","Wildfire claims"],"openingHoursSpecification":[{"@type":"OpeningHoursSpecification","dayOfWeek":["Monday","Tuesday","Wednesday","Thursday","Friday"],"opens":"07:00","closes":"17:00"}]},{"@type":"WebSite","@id":"https://hawaiiinsuranceappraiser.com/#website","url":"https://hawaiiinsuranceappraiser.com/","name":"Hawaii Insurance Appraiser","publisher":{"@id":"https://hawaiiinsuranceappraiser.com/#business"},"inLanguage":"en-US"},{"@type":"WebPage","@id":"https://hawaiiinsuranceappraiser.com/property-claim-glossary/#webpage","url":"https://hawaiiinsuranceappraiser.com/property-claim-glossary/","name":"Property Claim Glossary | ACV, Umpire, GET & More","description":"A searchable property claim glossary: actual cash value, appraisal award, umpire, hurricane deductible, AOAO, GET, HPIA and more.","inLanguage":"en-US","isPartOf":{"@id":"https://hawaiiinsuranceappraiser.com/#website"},"about":{"@id":"https://hawaiiinsuranceappraiser.com/#business"},"publisher":{"@id":"https://hawaiiinsuranceappraiser.com/#business"},"dateModified":"2026-11-17","primaryImageOfPage":{"@type":"ImageObject","@id":"https://hawaiiinsuranceappraiser.com/property-claim-glossary/#primaryimage","url":"https://hawaiiinsuranceappraiser.com/assets/img/photos/calculator-documents.webp","width":960,"height":640},"breadcrumb":{"@id":"https://hawaiiinsuranceappraiser.com/property-claim-glossary/#breadcrumb"},"mainEntity":{"@id":"https://hawaiiinsuranceappraiser.com/property-claim-glossary/#definedtermset"}},{"@type":"BreadcrumbList","itemListElement":[{"@type":"ListItem","position":1,"name":"Home","item":"https://hawaiiinsuranceappraiser.com/"},{"@type":"ListItem","position":2,"name":"Claim glossary","item":"https://hawaiiinsuranceappraiser.com/property-claim-glossary/"}],"@id":"https://hawaiiinsuranceappraiser.com/property-claim-glossary/#breadcrumb"},{"@type":"DefinedTermSet","name":"Property insurance claim glossary","url":"https://hawaiiinsuranceappraiser.com/property-claim-glossary/","hasDefinedTerm":[{"@type":"DefinedTerm","name":"Actual cash value (ACV)","description":"Replacement cost minus depreciation. Many policies pay ACV first and release the rest after repairs are complete.","inDefinedTermSet":"https://hawaiiinsuranceappraiser.com/property-claim-glossary/#definedtermset"},{"@type":"DefinedTerm","name":"Additional living expenses (ALE)","description":"Coverage for the increase in living costs, such as rent or meals, while your home is uninhabitable after a covered loss.","inDefinedTermSet":"https://hawaiiinsuranceappraiser.com/property-claim-glossary/#definedtermset"},{"@type":"DefinedTerm","name":"Amount of loss","description":"The dollar value of a covered loss. It is the question an appraisal panel normally decides.","inDefinedTermSet":"https://hawaiiinsuranceappraiser.com/property-claim-glossary/#definedtermset"},{"@type":"DefinedTerm","name":"AOAO","description":"Association of Apartment Owners – the governing body of a Hawaii condominium, which typically buys the master policy for the building.","inDefinedTermSet":"https://hawaiiinsuranceappraiser.com/property-claim-glossary/#definedtermset"},{"@type":"DefinedTerm","name":"Appraisal award","description":"The written decision, signed by at least two of the three panel members, that sets the amount of loss.","inDefinedTermSet":"https://hawaiiinsuranceappraiser.com/property-claim-glossary/#definedtermset"},{"@type":"DefinedTerm","name":"Appraisal clause","description":"The policy provision allowing either party to demand appraisal when they disagree on the amount of a covered loss.","inDefinedTermSet":"https://hawaiiinsuranceappraiser.com/property-claim-glossary/#definedtermset"},{"@type":"DefinedTerm","name":"Appraiser","description":"The person each side chooses to value the loss in appraisal. Policies usually require the appraiser to be competent and disinterested.","inDefinedTermSet":"https://hawaiiinsuranceappraiser.com/property-claim-glossary/#definedtermset"},{"@type":"DefinedTerm","name":"Betterment","description":"An improvement beyond the property’s pre-loss condition. Insurers may reduce payment for betterment, depending on policy wording.","inDefinedTermSet":"https://hawaiiinsuranceappraiser.com/property-claim-glossary/#definedtermset"},{"@type":"DefinedTerm","name":"Coverage A–D","description":"The main parts of a homeowners policy: A is the dwelling, B other structures, C personal property and D loss of use.","inDefinedTermSet":"https://hawaiiinsuranceappraiser.com/property-claim-glossary/#definedtermset"},{"@type":"DefinedTerm","name":"Debris removal","description":"Coverage for hauling away damaged materials after a covered loss, sometimes subject to a separate limit. Island disposal and freight costs can make it significant.","inDefinedTermSet":"https://hawaiiinsuranceappraiser.com/property-claim-glossary/#definedtermset"},{"@type":"DefinedTerm","name":"Declarations page","description":"The summary page of a policy listing the insured, property, coverage limits, deductibles and endorsements.","inDefinedTermSet":"https://hawaiiinsuranceappraiser.com/property-claim-glossary/#definedtermset"},{"@type":"DefinedTerm","name":"Deductible","description":"The portion of a covered loss you pay before the insurer pays. Hawaii policies may have separate deductibles for hurricane or other perils.","inDefinedTermSet":"https://hawaiiinsuranceappraiser.com/property-claim-glossary/#definedtermset"},{"@type":"DefinedTerm","name":"Depreciation","description":"The reduction in value for age, wear and condition, used to calculate actual cash value.","inDefinedTermSet":"https://hawaiiinsuranceappraiser.com/property-claim-glossary/#definedtermset"},{"@type":"DefinedTerm","name":"Endorsement","description":"A written change to a policy that adds, removes or modifies coverage.","inDefinedTermSet":"https://hawaiiinsuranceappraiser.com/property-claim-glossary/#definedtermset"},{"@type":"DefinedTerm","name":"Estimate","description":"An itemized calculation of the cost to repair or replace damaged property, typically broken into line items.","inDefinedTermSet":"https://hawaiiinsuranceappraiser.com/property-claim-glossary/#definedtermset"},{"@type":"DefinedTerm","name":"General excise tax (GET)","description":"Hawaii’s tax on business gross income, including contractor work, which is commonly passed on to customers. Rates vary by county, roughly 4% to about 4.7%.","inDefinedTermSet":"https://hawaiiinsuranceappraiser.com/property-claim-glossary/#definedtermset"},{"@type":"DefinedTerm","name":"Hawaii Hurricane Relief Fund (HHRF)","description":"A state fund created after Hurricane Iniki to provide hurricane coverage when private carriers pulled back. It later stopped writing policies once private coverage returned.","inDefinedTermSet":"https://hawaiiinsuranceappraiser.com/property-claim-glossary/#definedtermset"},{"@type":"DefinedTerm","name":"HO-6","description":"A condominium unit-owner policy covering the unit’s interior, contents, loss of use and often loss assessments.","inDefinedTermSet":"https://hawaiiinsuranceappraiser.com/property-claim-glossary/#definedtermset"},{"@type":"DefinedTerm","name":"HPIA","description":"The Hawaii Property Insurance Association, the state’s FAIR plan, best known for basic property coverage in Big Island lava zones 1 and 2.","inDefinedTermSet":"https://hawaiiinsuranceappraiser.com/property-claim-glossary/#definedtermset"},{"@type":"DefinedTerm","name":"Hurricane deductible","description":"A separate deductible, often a percentage of dwelling coverage, that applies when a hurricane causes the loss as defined in the policy.","inDefinedTermSet":"https://hawaiiinsuranceappraiser.com/property-claim-glossary/#definedtermset"},{"@type":"DefinedTerm","name":"Insurance Division (DCCA)","description":"The Hawaii state regulator of insurers, part of the Department of Commerce and Consumer Affairs and headed by the Insurance Commissioner. It accepts consumer complaints and inquiries.","inDefinedTermSet":"https://hawaiiinsuranceappraiser.com/property-claim-glossary/#definedtermset"},{"@type":"DefinedTerm","name":"Kona low","description":"A winter storm system that brings heavy rain and southerly winds from the usually sheltered leeward side of the islands.","inDefinedTermSet":"https://hawaiiinsuranceappraiser.com/property-claim-glossary/#definedtermset"},{"@type":"DefinedTerm","name":"Lava zone","description":"One of nine USGS lava hazard zones on the Big Island, with zone 1 the most hazardous. Zone affects insurance availability and pricing.","inDefinedTermSet":"https://hawaiiinsuranceappraiser.com/property-claim-glossary/#definedtermset"},{"@type":"DefinedTerm","name":"Line item","description":"A single entry in an estimate describing one task or material, with a quantity, unit and price.","inDefinedTermSet":"https://hawaiiinsuranceappraiser.com/property-claim-glossary/#definedtermset"},{"@type":"DefinedTerm","name":"Loss assessment coverage","description":"HO-6 coverage for your share of a special assessment the AOAO levies after a covered loss, up to the limit stated.","inDefinedTermSet":"https://hawaiiinsuranceappraiser.com/property-claim-glossary/#definedtermset"},{"@type":"DefinedTerm","name":"Master policy","description":"The policy an AOAO buys to insure the building and common elements of a condominium.","inDefinedTermSet":"https://hawaiiinsuranceappraiser.com/property-claim-glossary/#definedtermset"},{"@type":"DefinedTerm","name":"Matching","description":"The question of whether undamaged materials must be replaced so repairs match in color, texture or style. Treatment depends on policy wording and law.","inDefinedTermSet":"https://hawaiiinsuranceappraiser.com/property-claim-glossary/#definedtermset"},{"@type":"DefinedTerm","name":"Mitigation","description":"Reasonable steps to prevent further damage after a loss, such as tarping a roof or drying out water. Most policies require it.","inDefinedTermSet":"https://hawaiiinsuranceappraiser.com/property-claim-glossary/#definedtermset"},{"@type":"DefinedTerm","name":"Named peril","description":"A policy that covers only the causes of loss specifically listed, such as fire or windstorm.","inDefinedTermSet":"https://hawaiiinsuranceappraiser.com/property-claim-glossary/#definedtermset"},{"@type":"DefinedTerm","name":"Open peril","description":"A policy that covers all causes of loss except those specifically excluded.","inDefinedTermSet":"https://hawaiiinsuranceappraiser.com/property-claim-glossary/#definedtermset"},{"@type":"DefinedTerm","name":"Ordinance or law coverage","description":"Coverage for added costs to bring repaired property up to current building codes, often subject to a separate limit.","inDefinedTermSet":"https://hawaiiinsuranceappraiser.com/property-claim-glossary/#definedtermset"},{"@type":"DefinedTerm","name":"Overhead and profit (O&P)","description":"The general contractor’s charges for supervision, coordination and profit, often figured as a percentage of the job.","inDefinedTermSet":"https://hawaiiinsuranceappraiser.com/property-claim-glossary/#definedtermset"},{"@type":"DefinedTerm","name":"Proof of loss","description":"A sworn statement of the amount claimed, which some policies require within a set time or on request.","inDefinedTermSet":"https://hawaiiinsuranceappraiser.com/property-claim-glossary/#definedtermset"},{"@type":"DefinedTerm","name":"Public adjuster","description":"A licensed professional who represents policyholders in preparing and negotiating a claim, usually for a percentage fee.","inDefinedTermSet":"https://hawaiiinsuranceappraiser.com/property-claim-glossary/#definedtermset"},{"@type":"DefinedTerm","name":"Recoverable depreciation","description":"Depreciation withheld from an initial payment that the insurer pays once repairs are completed, under replacement cost policies.","inDefinedTermSet":"https://hawaiiinsuranceappraiser.com/property-claim-glossary/#definedtermset"},{"@type":"DefinedTerm","name":"Replacement cost value (RCV)","description":"The cost to repair or replace damaged property with materials of like kind and quality, without deduction for depreciation.","inDefinedTermSet":"https://hawaiiinsuranceappraiser.com/property-claim-glossary/#definedtermset"},{"@type":"DefinedTerm","name":"Reservation of rights","description":"A letter in which an insurer handles a claim while reserving the right to deny coverage later. It is a signal to consult an attorney.","inDefinedTermSet":"https://hawaiiinsuranceappraiser.com/property-claim-glossary/#definedtermset"},{"@type":"DefinedTerm","name":"Scope of loss","description":"The description of what was damaged and what work is needed to repair it, before pricing.","inDefinedTermSet":"https://hawaiiinsuranceappraiser.com/property-claim-glossary/#definedtermset"},{"@type":"DefinedTerm","name":"Square (roofing)","description":"A roofing unit equal to 100 square feet of roof surface.","inDefinedTermSet":"https://hawaiiinsuranceappraiser.com/property-claim-glossary/#definedtermset"},{"@type":"DefinedTerm","name":"Subrogation","description":"The insurer’s right, after paying a claim, to recover from a third party who caused the loss.","inDefinedTermSet":"https://hawaiiinsuranceappraiser.com/property-claim-glossary/#definedtermset"},{"@type":"DefinedTerm","name":"Suit limitation","description":"A policy provision setting how long you have to file a lawsuit against the insurer. Appraisal does not necessarily pause it.","inDefinedTermSet":"https://hawaiiinsuranceappraiser.com/property-claim-glossary/#definedtermset"},{"@type":"DefinedTerm","name":"Supplement","description":"A request for additional payment for damage or costs not included in the original estimate, often found during repairs.","inDefinedTermSet":"https://hawaiiinsuranceappraiser.com/property-claim-glossary/#definedtermset"},{"@type":"DefinedTerm","name":"Total loss","description":"A loss where the property is destroyed or repairs would cost more than the policy limit or the property’s value.","inDefinedTermSet":"https://hawaiiinsuranceappraiser.com/property-claim-glossary/#definedtermset"},{"@type":"DefinedTerm","name":"Trade winds","description":"The steady northeasterly winds that dominate Hawaii’s weather, keeping windward slopes wet and leeward areas dry.","inDefinedTermSet":"https://hawaiiinsuranceappraiser.com/property-claim-glossary/#definedtermset"},{"@type":"DefinedTerm","name":"Umpire","description":"The neutral third member of an appraisal panel who decides items the two appraisers cannot agree on.","inDefinedTermSet":"https://hawaiiinsuranceappraiser.com/property-claim-glossary/#definedtermset"},{"@type":"DefinedTerm","name":"Vog","description":"Volcanic smog formed from volcanic gases, most common on the Big Island’s west side. It can contribute to corrosion over time.","inDefinedTermSet":"https://hawaiiinsuranceappraiser.com/property-claim-glossary/#definedtermset"},{"@type":"DefinedTerm","name":"Xactimate","description":"Estimating software widely used by insurers, adjusters and contractors to price repairs by line item and region.","inDefinedTermSet":"https://hawaiiinsuranceappraiser.com/property-claim-glossary/#definedtermset"}],"@id":"https://hawaiiinsuranceappraiser.com/property-claim-glossary/#definedtermset"}]}</script>
</head>
